#!/usr/bin/env node
// SPDX-License-Identifier: Apache-2.0
// scripts/check-doc-freshness.mjs — generated by arbiter (T4, gold-doc-tranches-t3-t5.md §2.3).
// Per-doc freshness audit runner for this project. Delegates to `arbiter doc-set --freshness`
// via npx (no local install, no `yaml` dep — the engine runs inside arbiter's own environment
// against this repo, same shape as check-doc-set.mjs.ejs).
//
// Usage: node scripts/check-doc-freshness.mjs [--json]
//
// Exit codes (INV-53): 0=all graded docs fresh, 1=>=1 stale doc, 2=ERROR. Binary — there is no
// advisory mode inside the engine; softness (advisory/monthly/release-blocking) lives entirely in
// where this runner is WIRED (starter/standard/industrial pipelineStyle band), never in the script.
import { spawnSync } from 'node:child_process'

const args = process.argv.slice(2)

const result = spawnSync('npx', ['--no-install', 'arbiter', 'doc-set', '--freshness', ...args], {
  stdio: 'inherit',
  encoding: 'utf-8',
})

if (result.error) {
  process.stderr.write(
    `[doc-freshness] spawn error: ${result.error.message}\n`,
  )
  process.exit(2)
}

process.exit(result.status ?? 1)
